CREATE TABLE fulfilment_intents (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,product VARCHAR(32) NOT NULL,operation VARCHAR(32) NOT NULL,resource_id VARCHAR(32),request_hash VARCHAR(64) NOT NULL,idempotency_key VARCHAR(120) NOT NULL,price_pence BIGINT NOT NULL,status VARCHAR(32) NOT NULL,receipt TEXT,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE(user_id,idempotency_key),FOREIGN KEY(user_id) REFERENCES users(id));
